using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize]public class ActivitiesController:BaseController{private readonly ApplicationDbContext _db;private readonly IAuditService _audit;public ActivitiesController(ApplicationDbContext db,UserManager<ApplicationUser> users,IAuditService audit):base(users){_db=db;_audit=audit;}public async Task<IActionResult>Index(){var q=_db.Activities.AsQueryable();if(IsSales)q=q.Where(x=>x.AssignedTo==CurrentUserId);return View(await q.OrderByDescending(x=>x.ActivityDate).ToListAsync());}public IActionResult Create()=>View(new Activity{ActivityDate=DateTime.Today});[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(Activity model){if(!ModelState.IsValid)return View(model);model.AssignedTo=CurrentUserId;_db.Activities.Add(model);await _db.SaveChangesAsync();await _audit.LogAsync("Create","Activity",model.ActivityId.ToString(),newValue:model);return RedirectToAction(nameof(Index));}}
